  CUDA_VISIBLE_DEVICES=1 python ./scripts/run_benchmark.py --config-path "rolling_forecast_config.json" --data-name-list "ETTm1.csv" --strategy-args '{"horizon": 96}' --model-name "tst.TST" --model-hyper-params '{"pos_encoding": "sinespe", "base_freq": 22.54698477804209, "d_model": 16, "n_heads": 8, "num_layers": 1, "dim_feedforward": 2048, "dropout": 0.1, "norm": true, "seq_len": 96, "horizon": 96, "batch_size": 16, "lr": 0.0001, "num_epochs": 100, "patience": 5}' --deterministic "full" --gpus 0 --num-workers 1 --timeout 60000 --save-path "ETTm1_17thmar/TST_sine" --save-true-pred True
