}

case "${DATASET}" in
  ettm1) run_ettm1 ;;
  weather) run_weather ;;
  solar) run_solar ;;
  all)
    run_ettm1 &
    PID1=$!
    run_weather &
    PID2=$!
    run_solar &
    PID3=$!
    wait "${PID1}" "${PID2}" "${PID3}"
    ;;
  *)
    echo "Usage: $0 [ettm1|weather|solar|all]" >&2
    exit 1
    ;;
esac
